{
  "technical_and_design_decisions": [
    "For the Capabilities Framework (U1): Three separate capability maps are implemented at the root channel, application, and orderer levels, with only the V1.1 capability included per map for v1.1. Orderers enforce that orderer-level capabilities are enabled before application-level capabilities are enabled to prevent blockchain forks, and non-compatible binaries are terminated (crash) instead of using graceful degradation per v1.1 requirements.",
    "For RYW support (U2): The GetTrxState(key string) API is added to the chaincode shim with optional enablement via chaincode metadata to maintain backward compatibility with existing chaincodes.",
    "For the organization addition guide (U3): The deliverable includes static topology diagrams (PPT-style), written step-by-step instructions, and a screen-recorded video demonstration of the process on a test network.",
    "For CouchDB performance testing (U4): Testing uses standard Fabric benchmark workloads with varying query complexities, dataset sizes, and network loads, with results reported as latency, throughput, and scalability metrics.",
    "For MSPConfig refactor (U5): MSPConfig is converted to an interface with a default implementation that preserves existing configtxgen behavior, with no modifications to the existing configtxgen tooling.",
    "For chaincode singleton removal (U6): Singletons are replaced with dependency-injected per-channel instances, with no changes to public chaincode APIs to avoid breaking existing chaincodes.",
    "For test config generation (U7): The World test config uses a YAML schema that maps directly to core.yaml and orderer.yaml fields, with configuration generation implemented via Go templates and input validation.",
    "For lifecycle validation interface (U8): The interface first returns static validation parameters for +lifecycle with an automatically generated majority org signature policy, with a placeholder for future support of channel config policy evaluation as endorsement policies."
  ],
  "assumptions": [
    "Full access to the existing Hyperledger Fabric v1.1 codebase, build environment, and test infrastructure is available for development.",
    "For U3, a pre-existing single-org Fabric v1.1 test network is available for video recording, with no setup effort counted towards the estimate.",
    "For U4, pre-configured CouchDB instances for testing are available, with no infrastructure setup effort included in the estimate.",
    "For U5, existing configtxgen tooling will remain unmodified, only the MSPConfig type is refactored to an interface.",
    "For U6, existing chaincode regression tests are available to validate the singleton refactor, with no new test coverage for chaincode functionality required beyond regression testing.",
    "For U7, the World test config schema is already defined, only the configuration generation code needs to be implemented.",
    "For U8, the new lifecycle codebase is already partially implemented, only the validation interface and +lifecycle edge case need to be added."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement Capabilities Framework core functionality",
      "activity_description": "Extend channel configuration to add three separate capability maps (root channel, application, orderer), implement capability validation logic for peer and orderer binaries, add enforcement logic to ensure orderer capabilities are enabled before application capabilities to prevent forks, crash non-compatible participants per v1.1 requirements, update configtxgen tool to support setting the V1.1 capability in all three maps, document the process for linking non-backwards compatible changes to FAB-6000 and FAB-5999 tickets.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement Read-Your-Writes (RYW) API for chaincode",
      "activity_description": "Add GetTrxState(key string) method to the chaincode shim interface, implement backend peer logic to track transaction state and return requested keys for active transactions, add optional enablement flag via chaincode metadata to maintain backward compatibility with existing chaincodes, update chaincode documentation for the new API.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3",
      "activity_name": "Create organization addition guide and demo video",
      "activity_description": "Create static topology diagrams showing network state before and after organization addition, write step-by-step written guide for adding organizations to a running network without downtime, record screen-captured video demonstrating the process on a test network, edit and publish the final guide and video.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A4",
      "activity_name": "Conduct CouchDB query performance testing and reporting",
      "activity_description": "Design and execute benchmark tests for Fabric queries against CouchDB state database, test varying query complexities, dataset sizes, and network loads, analyze test results to produce a performance report with latency, throughput, and scalability metrics.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A5",
      "activity_name": "Refactor MSPConfig to interface for external config construction",
      "activity_description": "Convert existing MSPConfig struct to an interface, provide a default implementation matching existing configtxgen behavior, update all internal code references to use the interface, add example code and documentation for constructing channel config blocks outside of the configtxgen tool.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6",
      "activity_name": "Remove chaincode singletons for lifecycle prerequisite",
      "activity_description": "Refactor existing chaincode singleton instances to use dependency-injected per-channel instances, update all chaincode launch and management code to use the new instance model, run full regression tests to ensure existing chaincode functionality remains unbroken.",
      "most_likely_effort": 9
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement World test config to core/orderer YAML generation",
      "activity_description": "Implement code to generate peer core.yaml and orderer.yaml configuration files from values defined in the World test config, use Go templates to map World config fields to target config file fields, add validation to ensure generated configs are valid and complete.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement chaincode validation interface for new lifecycle",
      "activity_description": "Implement interface to return validation parameters for chaincodes, add special edge case handling for +lifecycle to return an automatically generated majority org signature policy, add placeholder support for future channel config policy evaluation as endorsement policies.",
      "most_likely_effort": 6
    }
  ],
  "reported_total": {
    "most_likely_effort": 57
  }
}

